/**
 * Basic Agent Example
 *
 * A minimal agent setup using @openserv-labs/sdk and @openserv-labs/client.
 * Just define, provision, and run!
 *
 * Run with: npx tsx basic-agent.ts
 */
import 'dotenv/config'
import { Agent, run } from '@openserv-labs/sdk'
import { provision, triggers } from '@openserv-labs/client'
import { z } from 'zod'

// 1. Define your agent
const agent = new Agent({
  systemPrompt: 'You are a helpful assistant that greets users.'
})

// 2. Add capabilities
agent.addCapability({
  name: 'greet',
  description: 'Greet a user by name',
  inputSchema: z.object({
    name: z.string().describe('The name of the user to greet')
  }),
  async run({ args }) {
    console.log(`Greeting: ${args.name}`)
    return `Hello, ${args.name}! Welcome to OpenServ.`
  }
})

async function main() {
  // 3. Provision with agent instance binding (v2.1+)
  // Binds API key and auth token directly to agent - no env vars needed!
  const result = await provision({
    agent: {
      instance: agent, // Calls agent.setCredentials() automatically
      name: 'basic-greeter',
      description: 'A simple greeting agent'
    },
    workflow: {
      name: 'Welcome Wizard',
      goal: 'Welcome users by name with a warm, personalized greeting message',
      trigger: triggers.webhook({
        waitForCompletion: true,
        input: {
          name: { type: 'string', title: 'Your Name', description: 'Who should we greet?' }
        }
      }),
      task: { description: 'Greet the user' }
    }
  })

  console.log(`Webhook: https://api.openserv.ai/webhooks/trigger/${result.triggerToken}`)

  // 4. Run the agent - credentials already bound via provision()
  await run(agent)
}

main().catch(console.error)

/**
 * Capability Example
 *
 * Demonstrates how to create capabilities — both runless and runnable with generate().
 */
import { Agent } from '@openserv-labs/sdk'
import { z } from 'zod'

const agent = new Agent({
  systemPrompt: 'You are a text analysis assistant.'
})

// Runless capability — platform handles the AI call, no run function needed
agent.addCapability({
  name: 'quickSummary',
  description: 'Provide a brief one-paragraph summary of the given text.'
})

// Runless capability with structured output
agent.addCapability({
  name: 'extractKeywords',
  description: 'Extract the top keywords from the given text.',
  outputSchema: z.object({
    keywords: z.array(z.string()).describe('Top keywords from the text'),
    language: z.string().describe('Detected language of the text')
  })
})

// Runnable capability using generate() — platform-delegated LLM call, no API key needed
agent.addCapability({
  name: 'analyzeText',
  description: 'Analyze text for sentiment and key themes',
  inputSchema: z.object({
    text: z.string().describe('The text to analyze'),
    depth: z.enum(['quick', 'detailed']).optional().describe('Analysis depth')
  }),
  async run({ args, action }) {
    const { text, depth = 'quick' } = args
    console.log(`Analyzing text (${depth} mode): "${text.slice(0, 50)}..."`)

    // Use generate() instead of direct OpenAI calls — no API key needed!
    const analysis = await this.generate({
      prompt: `Analyze the following text. Provide ${
        depth === 'detailed' ? 'comprehensive' : 'brief'
      } analysis of sentiment and key themes.\n\nText: ${text}`,
      action
    })

    return analysis
  }
})

export { agent }

/**
 * Capability with Agent Methods Example
 *
 * Demonstrates using agent methods (this.generate, this.addLogToTask, this.uploadFile, etc.)
 * inside capabilities. Uses generate() for platform-delegated LLM calls — no API key needed.
 */
import { Agent } from '@openserv-labs/sdk'
import { z } from 'zod'

const agent = new Agent({
  systemPrompt: 'You are a report generation assistant.'
})

agent.addCapability({
  name: 'generateReport',
  description: 'Generate a report and save it to the workspace',
  inputSchema: z.object({
    topic: z.string().describe('Report topic'),
    format: z.enum(['brief', 'detailed']).optional()
  }),
  async run({ args, action }) {
    const { topic, format = 'brief' } = args

    // Only log/upload if we're in a task context
    if (action?.type === 'do-task' && action.task) {
      const { workspace, task } = action

      // Log progress
      await this.addLogToTask({
        workspaceId: workspace.id,
        taskId: task.id,
        severity: 'info',
        type: 'text',
        body: `Starting ${format} report on "${topic}"...`
      })

      // Generate report using platform-delegated LLM call (no API key needed)
      const report = await this.generate({
        prompt: `Generate a ${format} report on the following topic: ${topic}`,
        action
      })

      // Upload as file
      await this.uploadFile({
        workspaceId: workspace.id,
        path: `reports/${topic.replace(/\s+/g, '-').toLowerCase()}.txt`,
        file: report,
        taskIds: [task.id]
      })

      // Log completion
      await this.addLogToTask({
        workspaceId: workspace.id,
        taskId: task.id,
        severity: 'info',
        type: 'text',
        body: 'Report generated and saved!'
      })

      return report
    }

    // Fallback if no task context
    return await this.generate({
      prompt: `Generate a ${format} report on the following topic: ${topic}`,
      action
    })
  }
})

export { agent }

/**
 * Error Handling Example
 *
 * Demonstrates proper error handling in capabilities.
 */
import { Agent } from '@openserv-labs/sdk'
import { z } from 'zod'

const agent = new Agent({
  systemPrompt: 'You are an assistant with robust error handling.',
  onError: (error, context) => {
    // Custom error handler for the agent
    console.error('Agent error:', error.message, context)
  }
})

agent.addCapability({
  name: 'riskyOperation',
  description: 'An operation that might fail',
  inputSchema: z.object({
    shouldFail: z.boolean().optional().describe('Force failure for testing')
  }),
  async run({ args, action }) {
    try {
      // Log start
      if (action?.type === 'do-task' && action.task) {
        await this.addLogToTask({
          workspaceId: action.workspace.id,
          taskId: action.task.id,
          severity: 'info',
          type: 'text',
          body: 'Starting risky operation...'
        })
      }

      // Simulate potential failure
      if (args.shouldFail) {
        throw new Error('Intentional failure for testing')
      }

      // Success
      return 'Operation completed successfully!'
    } catch (error: any) {
      // Log error
      if (action?.type === 'do-task' && action.task) {
        await this.addLogToTask({
          workspaceId: action.workspace.id,
          taskId: action.task.id,
          severity: 'error',
          type: 'text',
          body: `Error: ${error.message}`
        })

        // Mark task as errored
        await this.markTaskAsErrored({
          workspaceId: action.workspace.id,
          taskId: action.task.id,
          error: error.message
        })
      }

      throw error
    }
  }
})

export { agent }

/**
 * File Operations Example
 *
 * Demonstrates workspace file operations.
 */
import { Agent } from '@openserv-labs/sdk'
import { z } from 'zod'

const agent = new Agent({
  systemPrompt: 'You are a file management assistant.'
})

agent.addCapability({
  name: 'listFiles',
  description: 'List all files in the workspace',
  inputSchema: z.object({}),
  async run({ action }) {
    if (action?.type !== 'do-task') return 'No workspace context'

    const files = await this.getFiles({ workspaceId: action.workspace.id })

    return files.map(f => `- ${f.path} (${f.size} bytes)`).join('\n') || 'No files found'
  }
})

agent.addCapability({
  name: 'saveFile',
  description: 'Save content to a file',
  inputSchema: z.object({
    path: z.string().describe('File path'),
    content: z.string().describe('File content')
  }),
  async run({ args, action }) {
    if (action?.type !== 'do-task') return 'No workspace context'

    const result = await this.uploadFile({
      workspaceId: action.workspace.id,
      path: args.path,
      file: args.content,
      taskIds: action.task ? [action.task.id] : undefined
    })

    return `File saved: ${result.fullUrl}`
  }
})

agent.addCapability({
  name: 'removeFile',
  description: 'Delete a file from the workspace',
  inputSchema: z.object({
    fileId: z.number().describe('File ID to delete')
  }),
  async run({ args, action }) {
    if (action?.type !== 'do-task') return 'No workspace context'

    await this.deleteFile({
      workspaceId: action.workspace.id,
      fileId: args.fileId
    })

    return `File ${args.fileId} deleted`
  }
})

export { agent }

/**
 * Haiku Poet Agent Example (Runless Capability)
 *
 * A paid agent that generates haikus — no LLM API key needed!
 * Uses a runless capability: just name + description, the platform handles the AI call.
 *
 * Run with: npx tsx haiku-poet-agent.ts
 */
import 'dotenv/config'
import { Agent, run } from '@openserv-labs/sdk'
import { provision, triggers } from '@openserv-labs/client'

// 1. Define your agent
const agent = new Agent({
  systemPrompt: 'You are a haiku poet. Generate beautiful haikus when asked.'
})

// 2. Add a runless capability — no run function, no API key needed!
//    The platform handles the AI call automatically.
agent.addCapability({
  name: 'generate_haiku',
  description:
    'Generate a haiku poem (5-7-5 syllables) about the given input. Only output the haiku, nothing else.'
})

async function main() {
  // 3. Provision with agent instance binding
  const result = await provision({
    agent: {
      instance: agent, // Binds credentials directly to agent
      name: 'haiku-poet',
      description: 'A poet that creates beautiful haikus on any topic'
    },
    workflow: {
      name: 'Haiku Poetry Generator',
      goal: 'Transform any theme or emotion into a beautiful traditional 5-7-5 haiku poem using AI',
      trigger: triggers.x402({
        name: 'Haiku Poetry Generator',
        description: 'Transform any theme into a beautiful traditional haiku poem',
        price: '0.01',
        input: {
          topic: {
            type: 'string',
            title: 'Inspiration for Your Haiku',
            description: 'Share a theme, emotion, or scene — nature, seasons, love, life moments'
          }
        }
      }),
      task: { description: 'Generate a haiku about the given topic' }
    }
  })

  console.log(`Paywall: ${result.paywallUrl}`)
  console.log(`Price: $0.01 per haiku`)

  // 4. Run the agent - credentials already bound
  await run(agent)
}

main().catch(err => {
  console.error('Error:', err.message)
  process.exit(1)
})

/**
 * Multiple Capabilities Example
 *
 * Demonstrates adding multiple capabilities — both runless and runnable with generate().
 * No LLM API key needed for any of these.
 */
import { Agent } from '@openserv-labs/sdk'
import { z } from 'zod'

const agent = new Agent({
  systemPrompt: 'You are a versatile text processing assistant.'
})

// Add multiple capabilities at once
agent.addCapabilities([
  // Runless capability — platform handles the AI call
  {
    name: 'summarize',
    description: 'Summarize the given text content in 100 words or less.'
  },
  // Runless capability with structured output
  {
    name: 'extractKeywords',
    description: 'Extract the top keywords from the given text.',
    outputSchema: z.object({
      keywords: z.array(z.string()).describe('Extracted keywords'),
      count: z.number().describe('Number of keywords extracted')
    })
  },
  // Runnable capability using generate() for custom logic
  {
    name: 'translate',
    description: 'Translate text to another language',
    inputSchema: z.object({
      text: z.string().describe('Text to translate'),
      targetLanguage: z.string().describe('Target language')
    }),
    async run({ args, action }) {
      // Use generate() for platform-delegated LLM call (no API key needed)
      const translation = await this.generate({
        prompt: `Translate the following text to ${args.targetLanguage}. Output only the translation, nothing else.\n\nText: ${args.text}`,
        action
      })
      return translation
    }
  }
])

export { agent }

/**
 * Task Management Example
 *
 * Demonstrates task-related agent methods.
 */
import { Agent } from '@openserv-labs/sdk'
import { z } from 'zod'

const agent = new Agent({
  systemPrompt: 'You are a task management assistant.'
})

agent.addCapability({
  name: 'processWithTasks',
  description: 'Process data while managing task status',
  inputSchema: z.object({
    data: z.string().describe('Data to process')
  }),
  async run({ args, action }) {
    if (action?.type !== 'do-task' || !action.task) {
      return 'No task context available'
    }

    const { workspace, task, me } = action

    try {
      // Update status to in-progress
      await this.updateTaskStatus({
        workspaceId: workspace.id,
        taskId: task.id,
        status: 'in-progress'
      })

      // Log progress
      await this.addLogToTask({
        workspaceId: workspace.id,
        taskId: task.id,
        severity: 'info',
        type: 'text',
        body: 'Starting data processing...'
      })

      // Simulate processing
      const result = `Processed: ${args.data}`

      // Log completion
      await this.addLogToTask({
        workspaceId: workspace.id,
        taskId: task.id,
        severity: 'info',
        type: 'text',
        body: 'Processing complete!'
      })

      return result
    } catch (error: any) {
      // Mark task as errored
      await this.markTaskAsErrored({
        workspaceId: workspace.id,
        taskId: task.id,
        error: error.message || 'Unknown error'
      })

      throw error
    }
  }
})

// Creating subtasks example
agent.addCapability({
  name: 'delegateWork',
  description: 'Create subtasks for other agents',
  inputSchema: z.object({
    description: z.string().describe('Task description')
  }),
  async run({ args, action }) {
    if (action?.type !== 'do-task' || !action.task) {
      return 'No task context available'
    }

    const { workspace, me } = action

    // Get available agents
    const agents = await this.getAgents({ workspaceId: workspace.id })

    // Create a subtask
    const newTask = await this.createTask({
      workspaceId: workspace.id,
      assignee: agents[0]?.id || me.id,
      description: args.description,
      body: 'Detailed instructions here',
      input: '',
      expectedOutput: 'Expected result',
      dependencies: []
    })

    return `Created task ${newTask.id}`
  }
})

export { agent }

# OpenServ SDK Reference

Quick reference for common patterns.

## Features

- **Built-in Tunnel** - `run()` auto-connects to `agents-proxy.openserv.ai` for local dev
- **No Endpoint URL Needed** - Skip `endpointUrl` in `provision()` during development
- **Automatic Port Fallback** - If port 7378 is busy, finds an available one
- **Direct Credential Binding** - Pass `agent.instance` to `provision()` for automatic credential binding
- **`setCredentials()` Method** - Manually bind API key and auth token to agent
- **`DISABLE_TUNNEL`** - Set `DISABLE_TUNNEL=true` in production to run HTTP server only (no WebSocket tunnel)
- **`FORCE_TUNNEL`** - Set `FORCE_TUNNEL=true` to force tunnel mode even with an `endpointUrl`
- **Public Health Check** - `/health` endpoint responds before auth middleware
- **Binary Tunnel Responses** - Tunnel sends binary frames, preserving gzip/images transparently

## Installation

```bash
npm install @openserv-labs/sdk @openserv-labs/client zod
```

> `openai` is only needed if you use `process()` for direct OpenAI calls. Most agents don't need it—use runless capabilities or `generate()` instead.

## Minimal Agent (Runless)

The simplest agent uses a runless capability—no `run` function, no API key:

```typescript
import 'dotenv/config'
import { Agent, run } from '@openserv-labs/sdk'
import { provision, triggers } from '@openserv-labs/client'

// 1. Define your agent
const agent = new Agent({
  systemPrompt: 'You are a helpful assistant.'
})

// 2. Add a runless capability (platform handles the AI call)
agent.addCapability({
  name: 'greet',
  description: 'Greet the user warmly and helpfully'
})

async function main() {
  // 3. Provision with agent instance binding (v2.1+)
  await provision({
    agent: {
      instance: agent, // Binds API key and auth token directly to agent
      name: 'my-agent',
      description: '...'
    },
    workflow: {
      name: 'Welcome Wizard',
      goal: 'Welcome users by name with a warm, personalized greeting message',
      trigger: triggers.webhook({ waitForCompletion: true })
    }
  })

  // 4. Run - auto-connects via agents-proxy.openserv.ai (no ngrok needed!)
  await run(agent)
}

main().catch(console.error)
```

> **Tip:** No need for ngrok or other tunneling tools - `run()` opens a tunnel automatically.

## Runless Capabilities

Runless capabilities have no `run` function—the platform handles the AI call automatically:

```typescript
// Simplest form
agent.addCapability({
  name: 'generate_haiku',
  description: 'Generate a haiku poem (5-7-5 syllables) about the given input.'
})

// With custom inputSchema
agent.addCapability({
  name: 'translate',
  description: 'Translate text to the target language.',
  inputSchema: z.object({
    text: z.string(),
    targetLanguage: z.string()
  })
})

// With structured output via outputSchema
agent.addCapability({
  name: 'analyze_sentiment',
  description: 'Analyze sentiment of the given text.',
  outputSchema: z.object({
    sentiment: z.enum(['positive', 'negative', 'neutral']),
    confidence: z.number().min(0).max(1)
  })
})
```

**Rules:**
- Cannot have both `run` and `outputSchema`
- `inputSchema` is optional — defaults to `z.object({ input: z.string() })` if omitted
- `outputSchema` is optional — the platform uses it to generate structured output

## `generate()` — Platform-Delegated LLM Calls

Use `generate()` inside runnable capabilities to delegate LLM calls to the platform (no API key needed):

```typescript
agent.addCapability({
  name: 'createPost',
  description: 'Create a social media post',
  inputSchema: z.object({
    platform: z.enum(['twitter', 'linkedin']),
    topic: z.string()
  }),
  async run({ args, action }) {
    // Text generation
    const post = await this.generate({
      prompt: `Create a compelling ${args.platform} post about: ${args.topic}`,
      action
    })

    // Structured output
    const metadata = await this.generate({
      prompt: `Suggest 3 hashtags for: ${post}`,
      outputSchema: z.object({
        hashtags: z.array(z.string()).length(3)
      }),
      action
    })

    return `${post}\n\n${metadata.hashtags.map(t => `#${t}`).join(' ')}`
  }
})
```

Parameters:
- `prompt` (string) — The prompt for the LLM
- `action` (ActionSchema) — The action context from the `run` function
- `outputSchema` (Zod schema, optional) — Returns validated structured output
- `messages` (array, optional) — Conversation history for multi-turn generation

## Zod Schema Patterns

```typescript
// Required string
z.string().describe('Description')

// Optional with default
z.string().optional().default('value')

// Enum
z.enum(['a', 'b', 'c'])

// Number with constraints
z.number().min(1).max(100)

// Boolean
z.boolean().optional()

// Object
z.object({
  field: z.string(),
  nested: z.object({ sub: z.number() })
})

// Array
z.array(z.string())
```

## Trigger Types

```typescript
import { triggers } from '@openserv-labs/client'

// Webhook (free)
triggers.webhook({ waitForCompletion: true, timeout: 600 })

// x402 (paid)
triggers.x402({
  name: 'AI Service Name',
  description: 'What your service does',
  price: '0.01'
})

// Cron (scheduled)
triggers.cron({ schedule: '0 9 * * *' })

// Manual
triggers.manual()
```

## Multi-Agent Provision

`provision()` supports multi-agent workflows via `tasks` array and optional `agentIds`:

```typescript
const result = await provision({
  agent: { instance: agent, name: 'my-agent', description: '...' },
  workflow: {
    name: 'Supercharged Service Hub',
    goal: 'Execute a multi-agent pipeline where each step builds on the previous to deliver a complete service',
    trigger: triggers.x402({ name: 'Service', price: '0.01' }),
    tasks: [
      { name: 'step-1', description: 'First step' }, // assigned to provisioned agent
      { name: 'step-2', description: 'Second step', agentId: 1044 } // marketplace agent
    ]
    // edges auto-generated: trigger -> step-1 -> step-2
    // agentIds auto-derived from tasks
    // x402WalletAddress auto-injected from wallet
  }
})
```

- `task` (single) still works for backward compat
- `tasks` (array) enables multi-agent with per-task `agentId`
- `edges` are auto-generated sequentially if omitted
- `agentIds` are derived from tasks; explicit list adds extras (observers)
- x402 wallet address resolved automatically

See `openserv-multi-agent-workflows/examples/paid-image-pipeline.md` for a complete example.

## Agent Methods

```typescript
// In capability run function, use 'this':
async run({ args, action }) {
  // LLM generation (platform-delegated, no API key needed)
  const text = await this.generate({ prompt: '...', action })
  const structured = await this.generate({ prompt: '...', outputSchema: z.object({ ... }), action })

  // Tasks
  await this.addLogToTask({ workspaceId, taskId, severity: 'info', type: 'text', body: '...' })
  await this.updateTaskStatus({ workspaceId, taskId, status: 'in-progress' })
  await this.createTask({ workspaceId, assignee, description, body, input, dependencies })

  // Files
  await this.getFiles({ workspaceId })
  await this.uploadFile({ workspaceId, path, file })
  await this.deleteFile({ workspaceId, fileId })

}
```

## Payments API (x402)

```typescript
import { PlatformClient } from '@openserv-labs/client'

const client = new PlatformClient() // no API key or wallet needed for discovery

// Discover x402 services (no authentication required)
const services = await client.payments.discoverServices()

// Pay and execute an x402 workflow by ID (recommended)
const result = await client.payments.payWorkflow({
  workflowId: 123,
  input: { prompt: 'Hello' }
})

// Or by direct URL
const result = await client.payments.payWorkflow({
  triggerUrl: 'https://api.openserv.ai/webhooks/x402/trigger/...',
  input: { prompt: 'Hello' }
})

// Get trigger preflight info (no authentication required)
const preflight = await client.payments.getTriggerPreflight({ token: '...' })
```

## Web3 API (Credits Top-up)

```typescript
// Top up credits with USDC (uses WALLET_PRIVATE_KEY env var)
const result = await client.web3.topUp({ amountUsd: 10 })
console.log(`Added ${result.creditsAdded} credits`)

// Lower-level methods
const config = await client.web3.getUsdcTopupConfig()
await client.web3.verifyUsdcTransaction({ txHash: '0x...', payerAddress: '0x...', signature: '0x...' })
```

## ERC-8004: On-Chain Registration

Register after `provision()`, before `run()`. **Always wrap in try/catch** — registration requires ETH on Base for gas, and the wallet starts unfunded. Without try/catch, a failure here will crash the process and prevent `run(agent)` from starting.

**Important:** `provision()` writes `WALLET_PRIVATE_KEY` to `.env` at runtime. If you use `import 'dotenv/config'`, the env var is loaded once at startup (empty on first run) and never refreshed. Use `dotenv.config({ override: true })` after `provision()` to reload it:

```typescript
import dotenv from 'dotenv'
dotenv.config()

// ... after provision() ...

// Reload .env to pick up WALLET_PRIVATE_KEY written by provision()
dotenv.config({ override: true })

try {
  const client = new PlatformClient()
  await client.authenticate(process.env.WALLET_PRIVATE_KEY)

  const erc8004 = await client.erc8004.registerOnChain({
    workflowId: result.workflowId,       // from provision()
    privateKey: process.env.WALLET_PRIVATE_KEY!,
    name: 'My Agent',
    description: 'What this agent does',
    // chainId: 8453,                     // Default: Base mainnet
    // rpcUrl: 'https://mainnet.base.org' // Default
  })

  erc8004.agentId          // "8453:42"
  erc8004.txHash           // "0xabc..."
  erc8004.blockExplorerUrl // "https://basescan.org/tx/..."
  erc8004.agentCardUrl     // IPFS URL
  erc8004.scanUrl          // "https://www.8004scan.io/agents/base/42"
} catch (error) {
  console.warn('ERC-8004 registration skipped:', error instanceof Error ? error.message : error)
}
```

- First run → `register()` (new mint). Re-runs → `setAgentURI()` (update, same ID).
- **Never clear wallet state** unless you want a new agent ID.
- **Requires ETH on Base.** Fund the wallet logged during provisioning (`Created new wallet: 0x...`) with a small amount of ETH on Base mainnet before the first registration.

See **openserv-client** reference for full ERC-8004 API.

## Environment Variables

Most agents don't need any LLM API key—use runless capabilities or `generate()`. Only set `OPENAI_API_KEY` if you use `process()` for direct OpenAI calls.

```env
# Only needed for process() — most agents don't need this:
# OPENAI_API_KEY=your-key
# ANTHROPIC_API_KEY=your_anthropic_key  # If using Claude directly

